293	        {
294	            var playedToCompletion = false;
295	
296	            var runtimeTicks = item.GetRunTimeTicksForPlayState();
297	
298	            var positionTicks = reportedPositionTicks ?? runtimeTicks;
299	            var hasRuntime = runtimeTicks > 0;
300	
301	            // If a position has been reported, and if we know the duration
302	            if (positionTicks > 0 && hasRuntime && item is not AudioBook && item is not Book)
303	            {
304	                var pctIn = decimal.Divide(positionTicks, runtimeTicks) * 100;
305	
306	                if (pctIn < _config.Configuration.MinResumePct)
307	                {
308	                    // ignore progress during the beginning
309	                    positionTicks = 0;
310	                }
311	                else if (pctIn > _config.Configuration.MaxResumePct || positionTicks >= (runtimeTicks - TimeSpan.TicksPerSecond))
312	                {
313	                    // mark as completed close to the end
314	                    positionTicks = 0;
315	                    data.Played = playedToCompletion = true;
316	                }
317	                else
318	                {
319	                    // Enforce MinResumeDuration
320	                    var durationSeconds = TimeSpan.FromTicks(runtimeTicks).TotalSeconds;
321	                    if (durationSeconds < _config.Configuration.MinResumeDurationSeconds)
322	                    {
323	                        positionTicks = 0;
324	                        data.Played = playedToCompletion = true;
325	                    }
326	                }
327	            }
328	            else if (positionTicks > 0 && hasRuntime && item is AudioBook)
329	            {
330	                var playbackPositionInMinutes = TimeSpan.FromTicks(positionTicks).TotalMinutes;
331	                var remainingTimeInMinutes = TimeSpan.FromTicks(runtimeTicks - positionTicks).TotalMinutes;
332	
333	                if (playbackPositionInMinutes < _config.Configuration.MinAudiobookResume)
334	                {
335	                    // ignore progress during the beginning
336	                    positionTicks = 0;
337	                }
338	                else if (remainingTimeInMinutes < _config.Configuration.MaxAudiobookResume || positionTicks >= runtimeTicks)
339	                {
340	                    // mark as completed close to the end
341	                    positionTicks = 0;
342	                    data.Played = playedToCompletion = true;
343	                }
344	            }
345	            else if (!hasRuntime)
346	            {
347	                // If we don't know the runtime we'll just have to assume it was fully played
348	                data.Played = playedToCompletion = true;
349	                positionTicks = 0;
350	            }
351	
352	            if (!item.SupportsPlayedStatus)
353	            {
354	                positionTicks = 0;
355	                data.Played = false;
356	            }
357	
358	            if (!item.SupportsPositionTicksResume)
359	            {
360	                positionTicks = 0;
361	            }
362	
363	            data.PlaybackPositionTicks = positionTicks;
364	
365	            return playedToCompletion;
366	        }
367	    }
368	}
